function makeChoices(seed: DailyLessonSeed, ageIndex: number) {
  const signal = seed.signal.charAt(0).toLowerCase() + seed.signal.slice(1);
  const caution = seed.caution.charAt(0).toLowerCase() + seed.caution.slice(1);
  const wrongChoices = [
    [`Pick the first result before checking ${signal}`, `Assume one familiar example proves it always works, even though ${caution}`],
    [`Forward the first result to the group before checking ${signal}`, `Treat a friend's agreement as proof, even though ${caution}`],
    [`Choose the faster result and skip ${signal}`, `Treat one familiar case as proof despite this limit: ${caution}`],
  ][ageIndex];
  return [
    { text: seed.experiment, correct: true, feedback: seed.principle },
    { text: wrongChoices[0], correct: false, feedback: seed.caution },
    { text: wrongChoices[1], correct: false, feedback: `${seed.signal} A useful result still needs a person to check it.` },
  ];
}

function makeDailyActivity(seed: DailyLessonSeed, ageIndex: number): Lesson["activity"] {
  const example = seed.examples[ageIndex];
  const choices = makeChoices(seed, ageIndex);
  const challenge = [
    "Spot one clue and make a first guess.",
    "Compare your first guess with one extra clue before choosing.",
    "Name the tradeoff, test an edge case, and say what evidence could change your call.",
  ][ageIndex];
  const instruction = [
    `Your challenge: ${challenge} ${seed.experiment}`,
    `Your challenge: ${challenge} ${seed.experiment}`,
    `Your challenge: ${challenge} ${seed.experiment}`,
  ][ageIndex];
  const classifyItems = [
    [example, 0, seed.signal],
    [seed.caution, 1, seed.caution],
    [seed.experiment, 0, seed.principle],
  ].map(([text, category, why]) => ({ text, category: Number(category), why: String(why) }));
  const common = { scenario: example, prompt: `${example} ${challenge}` };
  switch (seed.activity) {
    case "predictor":
      return { kind: "predictor", title: `Steer the ${seed.topic} simulator`, instruction,
        prompt: `${example} What is the likeliest next clue?`, choices,
        contextPrompt: ageIndex === 0
          ? `Change one clue: ${seed.caution} What changes in the next guess?`
          : ageIndex === 1
            ? `Your friend spots a new detail: ${seed.signal} Does that change your first guess?`
            : `Now test the weak spot: ${seed.caution} Which tradeoff matters, and what would you verify?`,
        contextChoices: choices.map((choice, index) => ({ ...choice,
          text: index === 0 ? seed.experiment : choice.text })),
      };
    case "model-sorter":
      return { kind: "model-sorter", title: `Train Pip's tiny ${seed.topic} model`, instruction: `${instruction} Label the examples, train the model, then test its blind spot.`,
        ...common, categories: ["Pattern to notice", "Needs a second look"], items: classifyItems,
        testCase: ageIndex === 0
          ? `New card: ${seed.caution}`
          : ageIndex === 1
            ? `Your friend brings a card the model has not seen: ${seed.caution}`
            : `Edge case: the model meets a case outside its examples: ${seed.caution}`,
        testExplanation: `${seed.signal} ${ageIndex === 2 ? "Add a counterexample and check who could be affected." : "Add a different example, then test again."}` };
    case "hallucination":
      return { kind: "hallucination", title: "Detective desk: check the claim", instruction: `${instruction} Choose what needs evidence, then pick an independent way to verify it.`,
        ...common, categories: ["Checkable clue", "Claim to verify"], items: classifyItems,
        choices: [
          { text: ageIndex === 0 ? "Ask a trusted adult to help find a real source." : ageIndex === 1 ? "Open the original source before sharing it with the group." : "Trace the claim to independent evidence and check whether it supports this exact wording.", correct: true, feedback: `${seed.signal} ${seed.principle}` },
          { text: ageIndex === 0 ? "Believe it because it has a big number." : ageIndex === 1 ? "Share it because several friends reposted it." : "Treat polished wording or a familiar source name as enough proof.", correct: false, feedback: seed.caution },
          { text: ageIndex === 0 ? "Ask the same bot again and trust the repeat." : ageIndex === 1 ? "Ask another chatbot and count matching answers as proof." : "Use a second generated answer as if it were independent evidence.", correct: false, feedback: "Generated answers are not independent evidence; check an original source." },
        ] };
    case "real-or-ai":
      return { kind: "real-or-ai", title: "Evidence lab: inspect the source", instruction: `${instruction} Sort what you can see from what you still need to verify.`,
        ...common, categories: ["Real clue", "AI-made clue", "Cannot tell yet"], items: [
          { text: `TikTok: a celebrity appears to announce a surprising new rule. ${ageIndex === 0 ? "Check the official account." : ageIndex === 1 ? "Find the original upload and another reliable report." : "Trace the source and corroborate the claim before sharing."}`, category: 2, why: "A clip alone does not prove the speaker or claim." },
          { text: "A voice note from Grandma urgently asks for a gift card and says not to call.", category: 2, why: "A familiar voice can be copied. Call a number you already trust." },
          { text: "A screenshot of a breaking headline comes from an account with 12 followers.", category: 2, why: "A screenshot can be edited; check whether a reliable outlet published it." },
          { text: "The same story appears as a video from a verified news channel.", category: 0, why: "The source is stronger context, but open the report and check what it confirms." },
        ] };
    case "redactor":
      return { kind: "redactor", title: "Privacy shield: redact a pretend prompt", instruction: `${instruction} Black out the details that could identify or expose someone.`,
        ...common, items: [
          { text: ageIndex === 0 ? "My pretend name is Rowan Example." : ageIndex === 1 ? "A group-chat screenshot shows Rowan's handle." : "A project note includes a real person's account handle.", category: 1, why: "Names and handles can identify someone." },
          { text: ageIndex === 0 ? "My pretend school is Example Middle." : ageIndex === 1 ? "The screenshot shows the school's name and after-school route." : "The attachment reveals a location and a regular schedule.", category: 1, why: "School, location, and schedule details can expose someone." },
          { text: "A made-up moon is called Blue Pebble.", category: 0, why: "An invented story detail is not identifying." },
          { text: `The task is: ${seed.experiment}`, category: 0, why: "Keep the useful task and remove details the tool does not need." },
        ] };
    case "prompt-fixer":
      return { kind: "prompt-fixer", title: `Prompt workshop: improve ${seed.topic}`, instruction: `${instruction} Upgrade the weak request without adding private details.`,
        ...common, prompt: `${example} Weak request: "Help me with this." ${seed.experiment}`,
        fields: ageIndex === 0 ? ["goal", "safe context", "format", "limit"] : ageIndex === 1 ? ["goal", "useful context", "format", "limit"] : ["goal", "relevant context", "output format", "limits"] };
    case "ai-sorter":
      return { kind: "ai-sorter", title: "Choose the right lane for AI", instruction: `${instruction} Sort each choice by its real risk and who should decide.`,
        ...common, categories: ["Okay with family rules", "Ask an adult first", "Do not use AI for this"],
        items: [
          { text: `${example} ${ageIndex === 0 ? "Try the pretend version first." : ageIndex === 1 ? "Check the teacher or family rule before trying it." : "Compare the benefit with the privacy, fairness, or accuracy risk before choosing."}`, category: ageIndex === 0 ? 0 : ageIndex === 1 ? 1 : 1, why: `${seed.signal} ${ageIndex === 2 ? "The tradeoff needs a human check." : "Permission and context matter."}` },
          { text: ageIndex === 0 ? "Ask a bot what medicine to take." : ageIndex === 1 ? "Let a chatbot decide whether a friend needs medical help." : "Use a generated answer as the final call on someone's health, money, or safety.", category: 2, why: "High-stakes decisions need responsible human help." },
          { text: ageIndex === 0 ? "Paste a password so the bot can log in." : ageIndex === 1 ? "Upload a friend's private screenshot to get advice." : "Send private records or credentials because the result might be more personalized.", category: 2, why: "Keep secrets and other people's private information out." },
        ] };
    case "app-planner":
      return { kind: "app-planner", title: "Build a safe five-part idea", instruction: `${instruction} Sketch the smallest version and test one awkward case.`,
        ...common, prompt: `${example} ${seed.experiment}`,
        fields: ["problem", "user", "screens", "main action", "safety check"] };
    case "branching":
      return { kind: "branching", title: `Choose the next move: ${seed.topic}`, instruction,
        ...common, choices };
    default:
      return { kind: "branching", title: seed.title, instruction, ...common, choices };
  }
}

function makeChecks(seed: DailyLessonSeed, ageIndex: number): [string, string, string, string, string][] {
  const example = seed.examples[ageIndex];
  const caution = seed.caution.charAt(0).toLowerCase() + seed.caution.slice(1);
  const wrong = [
    ["Pick the first result without checking the clue.", `Assume the tool knows the whole story even though ${caution}`],
    [`Forward the result before checking ${seed.signal.toLowerCase()}`, `Treat a friend's repost as proof even though ${caution}`],
    [`Skip the extra check to save time, even though ${caution}`, "Treat a strong result on one case as proof for every case."],
  ][ageIndex];
  return [
    [`${example} What is the best next move?`, seed.experiment, wrong[0], wrong[1], `${seed.signal} ${seed.principle}`],
    [`Which clue in this moment could change the result: ${example}`, seed.signal, wrong[1], "Only whether the answer sounds smooth.", seed.signal],
    [`What small test would tell you more about ${seed.topic}?`, seed.experiment, wrong[0], "Keep the first result and never compare it.", `${seed.experiment} ${seed.caution}`],
    [`What could go wrong if someone trusts this result too quickly?`, seed.caution, wrong[0], "A polished screen removes the need for a person.", seed.caution],
    [`${ageIndex === 0 ? "Tell Pip" : ageIndex === 1 ? "Explain to your friend" : "Make the call"}: ${example} What would you check before acting?`, seed.signal, wrong[1], "The tool has human feelings and full understanding.", `${seed.signal} ${seed.principle}`],
  ];
}

function makeDailyScripts(seed: DailyLessonSeed, ageIndex: number): [string, string, string] {
  const example = seed.examples[ageIndex];
  const voice = ["Pip", "Echo", "Nova"][ageIndex];
  const scenarios = [
    [
      `${voice} here! ${example} Watch for one clue: ${seed.signal} AI makes a guess from patterns. It is not reading your mind. Let's see what happens when we change one small thing.`,
      `${seed.principle} ${seed.caution} Spot the clue, make a guess, and see if the next result changes. A funny miss can teach us more than a perfect guess.`,
      `${seed.experiment} Tell a trusted grown-up what you noticed. If a real choice feels risky, stop and ask for help. Mission complete—take a break and come back tomorrow for the next experiment.`,
    ],
    [
      `${voice} here. ${example} What would you predict? ${seed.principle} Keep your first guess, then compare it with what the tool shows. The difference is a clue.`,
      `${seed.signal} Change one detail and compare the result. ${seed.caution} If a friend shares the answer, check the clue before you repeat it. A confident tone is not proof.`,
      `${seed.experiment} Say what changed and what you would verify. If the choice affects safety, money, health, or someone else's privacy, pause and involve a trusted adult. Take a break and return tomorrow.`,
    ],
    [
      `${voice} here. ${example} The useful question is not just "Did it work?" Ask what clue it used and who benefits from the result. ${seed.principle}`,
      `${seed.signal} Change one condition and look for a case the first test missed. ${seed.caution} The best-looking result may still have a cost or a blind spot.`,
      `${seed.experiment} Name the tradeoff and the evidence that would change your call. For high-stakes choices, bring in a trusted adult. You have reached a natural stopping point; come back tomorrow if you want another round.`,
    ],
  ];
  return scenarios.map((scenes) => scenes.map((scene) => scene.trim()).join("~")) as [string, string, string];
}

export function dailySeedAsLessonSeed(seed: DailyLessonSeed, chapterId: Lesson["levelId"], ageIndex: number) {
  const scenarios = seed.examples;
  return {
    id: seed.id,
    levelId: chapterId,
    title: seed.title,
    topic: seed.topic,
    scenarios,
    scripts: makeDailyScripts(seed, ageIndex),
    visuals: [
      `${seed.topic}: input clue → learned pattern → possible result`,
      `Evidence to inspect: ${seed.signal}`,
      `Try the safe experiment: ${seed.experiment}`,
    ] as [string, string, string],
    action: seed.experiment,
    unsafe: seed.caution,
    takeaway: seed.principle,
    steps: [
      "Notice the input",
      "Name the pattern",
      "Change one clue",
      "Check the result",
    ] as [string, string, string, string],
    checks: makeChecks(seed, ageIndex),
    activity: makeDailyActivity(seed, ageIndex),
    reflect: `Explain ${seed.topic} in your own words. What clue would you check before trusting its result, and why?`,
    family: `Where might we notice ${seed.topic} in everyday life, and what would we check together?`,
  };
}
